/**
 * Build a one-file old-vs-new comparison CSV from two backend-stage-*.csv runs.
 *
 * Usage:
 *   node scripts/build-run-comparison.js <old.csv> <new.csv> <oldLabel> <newLabel> [output.csv]
 *
 * Matches questions present in BOTH files (exact question text), emits per-stage
 * DELTA (ms) for each run + Δ (new - old), plus Total + Δ% , and AVG/MAX/MIN
 * rows computed over the shared questions only.
 *
 * Generated by Claude.
 */
const fs = require('fs')
const path = require('path')

const [oldPath, newPath, oldLabel, newLabel] = process.argv.slice(2)
const outputPath = process.argv[6] ||
  path.join(path.dirname(newPath), 'comparison-' + oldLabel.replace(/[^\w.-]/g, '') + '-vs-' + newLabel.replace(/[^\w.-]/g, '') + '.csv')

if (!oldPath || !newPath || !oldLabel || !newLabel) {
  console.error('Usage: node build-run-comparison.js <old.csv> <new.csv> <oldLabel> <newLabel> [out.csv]')
  process.exit(1)
}

function parseCsvLine(line) {
  const out = []
  let cur = '', inQ = false
  for (let i = 0; i < line.length; i++) {
    const c = line[i]
    if (inQ) {
      if (c === '"' && line[i + 1] === '"') { cur += '"'; i++ }
      else if (c === '"') inQ = false
      else cur += c
    } else {
      if (c === ',') { out.push(cur); cur = '' }
      else if (c === '"') inQ = true
      else cur += c
    }
  }
  out.push(cur)
  return out
}

function num(s) {
  if (s == null) return null
  const m = String(s).replace(/\s/g, '').match(/-?\d+/) // handles "+46", "+-53", "7744 ms"
  return m ? parseInt(m[0], 10) : null
}

// Parse a backend-stage file into { questionText: {answerLen, total, stageOrder:[], stages:{name:delta}} }
function parseRun(p) {
  const lines = fs.readFileSync(p, 'utf8').replace(/\r\n/g, '\n').split('\n')
  const runs = {}
  let cur = null
  for (const raw of lines) {
    const cells = parseCsvLine(raw)
    const key = cells[0]
    if (key === 'Question') {
      const q = cells[1]
      cur = { q, answerLen: null, total: null, stageOrder: [], stages: {} }
      runs[q] = cur
    } else if (key === 'Answer Length' && cur) {
      cur.answerLen = num(cells[1])
    } else if (key === 'Total' && cur) {
      cur.total = num(cells[2] || cells[1])
    } else if (cur && key && cells[2] !== undefined && key !== 'STAGE' && key !== 'User' && key !== 'Run 1') {
      // stage row: STAGE, TIMESTAMP, DELTA(MS)
      const d = num(cells[2])
      if (d !== null && /:/.test(key)) {
        cur.stages[key] = d
        if (!cur.stageOrder.includes(key)) cur.stageOrder.push(key)
      }
    }
  }
  return runs
}

const oldRuns = parseRun(oldPath)
const newRuns = parseRun(newPath)

// Stage order: take it from the new run's first question (natural pipeline order),
// drop preDiscovery:start (always the 0-baseline).
const firstNew = Object.values(newRuns)[0]
const stages = firstNew.stageOrder.filter(s => s !== 'preDiscovery:start')

// Shared questions, in the new run's order
const shared = Object.keys(newRuns).filter(q => oldRuns[q])
const onlyOld = Object.keys(oldRuns).filter(q => !newRuns[q])

// Header
const header = ['Q', 'Question',
  `Answer length ${oldLabel}`, `Answer length ${newLabel}`,
  `Total ${oldLabel} (ms)`, `Total ${newLabel} (ms)`, 'Δ Total', 'Δ %']
for (const s of stages) header.push(`${s} — ${oldLabel}`, `${s} — ${newLabel}`, 'Δ')

const rows = [header]
const acc = {} // for averages: {col: [values]}
function pushAcc(k, v) { if (v != null) (acc[k] = acc[k] || []).push(v) }

shared.forEach((q, i) => {
  const o = oldRuns[q], n = newRuns[q]
  const dTotal = (n.total != null && o.total != null) ? n.total - o.total : ''
  const dPct = (n.total != null && o.total) ? `${dTotal > 0 ? '+' : ''}${Math.round((dTotal / o.total) * 100)}%` : ''
  pushAcc('totalOld', o.total); pushAcc('totalNew', n.total); pushAcc('dTotal', dTotal === '' ? null : dTotal)
  const row = [`Q${String(i + 1).padStart(2, '0')}`, q, o.answerLen, n.answerLen, o.total, n.total, dTotal, dPct]
  for (const s of stages) {
    const ov = o.stages[s] ?? '', nv = n.stages[s] ?? ''
    const d = (ov !== '' && nv !== '') ? nv - ov : ''
    row.push(ov, nv, d)
    pushAcc(s + '_o', ov === '' ? null : ov)
    pushAcc(s + '_n', nv === '' ? null : nv)
    pushAcc(s + '_d', d === '' ? null : d)
  }
  rows.push(row)
})

const avg = a => a && a.length ? Math.round(a.reduce((x, y) => x + y, 0) / a.length) : ''
const mx = a => a && a.length ? Math.max(...a) : ''
const mn = a => a && a.length ? Math.min(...a) : ''

function statRow(label, fn) {
  const r = [label, '', '', '', fn(acc.totalOld), fn(acc.totalNew), fn(acc.dTotal), '']
  for (const s of stages) r.push(fn(acc[s + '_o']), fn(acc[s + '_n']), fn(acc[s + '_d']))
  return r
}
rows.push(statRow('AVG', avg))
rows.push(statRow('MAX', mx))
rows.push(statRow('MIN', mn))

const esc = v => {
  const s = String(v ?? '')
  return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s
}
fs.writeFileSync(outputPath, rows.map(r => r.map(esc).join(',')).join('\n') + '\n')

console.log('Shared questions:', shared.length)
console.log('In old run but NOT new:', onlyOld.length ? onlyOld.join(' | ') : '(none)')
console.log('Stages compared:', stages.length)
console.log('Written:', outputPath)
